"use client";

import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { jsPDF } from "jspdf";

type Tab = "overview"|"transactions"|"accounts"|"budgets"|"goals"|"recurring"|"reports"|"categories";
type Kind = "income"|"expense"|"transfer";
type Account = {id:string;name:string;account_type:string;opening_balance:number;currency:string;is_active:boolean;balance:number};
type Category = {id:string;name:string;type:"income"|"expense";color:string;icon:string;is_default:boolean};
type Tx = {id:string;type:"income"|"expense";category:string;description:string;amount:number;transaction_date:string;created_at:string;account_id:string|null;transfer_to_account_id:string|null;transfer_group:string|null;account_name:string|null;transfer_to_account_name:string|null};
type Budget = {id:string;name:string;category:string;amount_limit:number;period:"weekly"|"monthly"|"yearly";starts_on:string;is_active:boolean};
type Goal = {id:string;name:string;target_amount:number;current_amount:number;target_date:string|null;status:"active"|"completed"|"paused"};
type Recurring = {id:string;name:string;type:"income"|"expense";category:string;description:string;amount:number;frequency:"weekly"|"biweekly"|"monthly"|"yearly";next_date:string;account_id:string|null;is_active:boolean};
type FinanceData = {profile:{name:string;emailHint:string}|null;transactions:Tx[];accounts:Account[];categories:Category[];budgets:Budget[];goals:Goal[];recurring:Recurring[];preferences:{widgets?:Record<string,boolean>;chartMode?:string;[k:string]:unknown}};
type Draft = {name:string;category:string;type:string;amount:string;description:string;date:string;accountId:string;openingBalance:string;accountType:string;period:string;startsOn:string;targetAmount:string;currentAmount:string;targetDate:string;frequency:string;nextDate:string;fromAccountId:string;toAccountId:string;color:string;icon:string};
const tabs:{id:Tab;label:string;glyph:string}[]=[
  {id:"overview",label:"Resumen",glyph:"⌂"},
  {id:"transactions",label:"Movimientos",glyph:"↕"},
  {id:"accounts",label:"Cuentas",glyph:"▣"},
  {id:"budgets",label:"Presupuestos",glyph:"◴"},
  {id:"goals",label:"Metas de ahorro",glyph:"◎"},
  {id:"recurring",label:"Recurrentes",glyph:"⟳"},
  {id:"reports",label:"Informes",glyph:"▥"},
  {id:"categories",label:"Categorías",glyph:"▦"}
];
const isoToday=()=>{const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");};
const monthKey=(d=new Date())=>d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");
const fmt=(v:number)=>new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN",maximumFractionDigits:2}).format(v||0);
const dateFmt=(v:string|null|undefined)=>v?new Date(v+"T12:00:00").toLocaleDateString("es-MX",{day:"2-digit",month:"short",year:"numeric"}):"Sin fecha";
const blankDraft=(data:FinanceData|null):Draft=>({name:"",category:"",type:"expense",amount:"",description:"",date:isoToday(),accountId:data?.accounts.find(a=>a.is_active)?.id||"",openingBalance:"0",accountType:"cash",period:"monthly",startsOn:isoToday(),targetAmount:"",currentAmount:"0",targetDate:"",frequency:"monthly",nextDate:isoToday(),fromAccountId:data?.accounts.find(a=>a.is_active)?.id||"",toAccountId:"",color:"#FF6E75",icon:"circle"});
const CAT_COLORS=["#B7F35A","#FF6E75","#58B6FF","#B49AFF","#FFBE69","#62D6C8","#E89BCB","#A9B4BE","#F58A62","#8EA3FF"];
const monthExpense = (t:Tx)=>t.type==="expense"&&!t.transfer_group;
const monthIncome = (t:Tx)=>t.type==="income"&&!t.transfer_group;
function startOfPeriod(date:string,period:string) {
  const d=new Date(date+"T12:00:00");
  if(period==="weekly"){const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);}
  else if(period==="yearly"){d.setMonth(0,1);}
  else d.setDate(1);
  return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
}
function periodName(p:string){return p==="weekly"?"Semanal":p==="yearly"?"Anual":"Mensual";}
function groupTransfers(txs:Tx[]) {
  const normal=txs.filter(t=>!t.transfer_group);
  const groups=new Map<string,Tx[]>();
  for(const t of txs.filter(t=>t.transfer_group)){const a=groups.get(t.transfer_group!)||[];a.push(t);groups.set(t.transfer_group!,a);}
  const transfers:Tx[]=[];
  for(const [group,rows] of groups){const out=rows.find(t=>t.type==="expense");const inside=rows.find(t=>t.type==="income");if(out&&inside)transfers.push({...out,id:group,type:"expense",category:"Transferencia",description:"Traspaso entre cuentas",amount:Math.abs(Number(out.amount)),transfer_to_account_id:inside.account_id,transfer_to_account_name:inside.account_name});}
  return [...normal,...transfers].sort((a,b)=>String(b.transaction_date).localeCompare(String(a.transaction_date)));
}
export default function FinanceModule(){
  const [data,setData]=useState<FinanceData|null>(null);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState("");
  const [message,setMessage]=useState("");
  const [tab,setTab]=useState<Tab>("overview");
  const [draft,setDraft]=useState<Draft>(blankDraft(null));
  const [formOpen,setFormOpen]=useState(false);
  const [txMode,setTxMode]=useState<Kind>("expense");
  const [editingTx,setEditingTx]=useState<Tx|null>(null);
  const [busy,setBusy]=useState(false);
  const [search,setSearch]=useState("");
  const [typeFilter,setTypeFilter]=useState("all");
  const [categoryFilter,setCategoryFilter]=useState("all");
  const [periodFilter,setPeriodFilter]=useState(monthKey());
  const [selectedSlice,setSelectedSlice]=useState("");
  const [settingsOpen,setSettingsOpen]=useState(false);
  const [goalAdds,setGoalAdds]=useState<Record<string,string>>({});
  const [budgetDraft,setBudgetDraft]=useState({name:"",category:"Vivienda",amountLimit:"",period:"monthly",startsOn:isoToday()});
  const [categoryDraft,setCategoryDraft]=useState({name:"",type:"expense",color:"#FF6E75",icon:"circle"});
  const [accountEdit,setAccountEdit]=useState<Account|null>(null);
  const [accountEditDraft,setAccountEditDraft]=useState({name:"",accountType:"cash",openingBalance:"0",isActive:true});

  const refresh=useCallback(async()=>{
    try{
      const r=await fetch("/api/finance",{cache:"no-store"});
      const j=await r.json();
      if(!r.ok||!j.ok)throw new Error(j.error||"No se pudo cargar FLUX.");
      setData(j.finance);setError("");
    }catch(e){setError(e instanceof Error?e.message:"No se pudo cargar el módulo financiero.");}
    finally{setLoading(false);}
  },[]);
  useEffect(()=>{void refresh();},[refresh]);
  useEffect(()=>{if(data&&!draft.accountId){setDraft(d=>({...d,accountId:data.accounts.find(a=>a.is_active)?.id||"",fromAccountId:data.accounts.find(a=>a.is_active)?.id||"",toAccountId:data.accounts.find(a=>a.is_active&&a.id!==d.fromAccountId)?.id||""}));}},[data,draft.accountId]);

  const transactions=data?.transactions||[];
  const accounts=data?.accounts||[];
  const categories=data?.categories||[];
  const budgets=data?.budgets||[];
  const goals=data?.goals||[];
  const recurring=data?.recurring||[];
  const preferences=data?.preferences||{};
  const prefsWidgets=preferences.widgets||{balance:true,trends:true,categories:true,budgets:true,goals:true};
  const currentMonth=monthKey();
  const currentMonthTx=useMemo(()=>transactions.filter(t=>String(t.transaction_date).slice(0,7)===currentMonth),[transactions,currentMonth]);
  const thisMonthIncome=currentMonthTx.filter(monthIncome).reduce((s,t)=>s+Number(t.amount),0);
  const thisMonthExpense=currentMonthTx.filter(monthExpense).reduce((s,t)=>s+Number(t.amount),0);
  const allBalance=accounts.filter(a=>a.is_active).reduce((s,a)=>s+Number(a.balance),0);
  const currentNet=thisMonthIncome-thisMonthExpense;
  const currentRecurring=recurring.filter(r=>r.is_active);
  const dueRecurring=currentRecurring.filter(r=>r.next_date<=isoToday());
  const displayTx=useMemo(()=>groupTransfers(transactions),[transactions]);
  const visibleTx=useMemo(()=>displayTx.filter(t=>{
    const q=search.toLowerCase();
    const matches=[t.description,t.category,t.account_name,t.transfer_to_account_name].join(" ").toLowerCase().includes(q);
    return matches&&(typeFilter==="all"||(typeFilter==="transfer"?!!t.transfer_group:t.type===typeFilter))&&(categoryFilter==="all"||t.category===categoryFilter);
  }),[displayTx,search,typeFilter,categoryFilter]);
  const expenseByCategory=useMemo(()=>{
    const m=new Map<string,number>();
    for(const t of currentMonthTx.filter(monthExpense))m.set(t.category,(m.get(t.category)||0)+Number(t.amount));
    return [...m.entries()].map(([name,amount],i)=>({name,amount,color:categories.find(c=>c.name===name&&c.type==="expense")?.color||CAT_COLORS[i%CAT_COLORS.length]})).sort((a,b)=>b.amount-a.amount);
  },[currentMonthTx,categories]);
  const pieTotal=expenseByCategory.reduce((s,c)=>s+c.amount,0);
  const pieCss=useMemo(()=>{if(!pieTotal)return "conic-gradient(#252b30 0deg 360deg)";let offset=0;const parts=expenseByCategory.map(c=>{const span=c.amount/pieTotal*360;const p=`${c.color} ${offset}deg ${offset+span}deg`;offset+=span;return p;});return "conic-gradient("+parts.join(",")+")";},[expenseByCategory,pieTotal]);
  const monthlySeries=useMemo(()=>Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-i));const key=monthKey(d);const label=d.toLocaleDateString("es-MX",{month:"short"});const ts=transactions.filter(t=>String(t.transaction_date).slice(0,7)===key);return {key,label,income:ts.filter(monthIncome).reduce((s,t)=>s+Number(t.amount),0),expense:ts.filter(monthExpense).reduce((s,t)=>s+Number(t.amount),0)};}),[transactions]);
  const budgetViews=useMemo(()=>budgets.filter(b=>b.is_active).map(b=>{const start=startOfPeriod(b.starts_on||isoToday(),b.period);const now=isoToday();const used=transactions.filter(t=>t.type==="expense"&&!t.transfer_group&&t.category===b.category&&String(t.transaction_date)>=start&&String(t.transaction_date)<=now).reduce((s,t)=>s+Number(t.amount),0);return {...b,used,remaining:Number(b.amount_limit)-used,ratio:Math.min(100,used/Number(b.amount_limit)*100)};}),[budgets,transactions]);
  const allTransactionsAmount=transactions.filter(t=>!t.transfer_group).reduce((s,t)=>s+Number(t.amount),0);
  const latest=displayTx.slice(0,7);

  async function mutate(path:string,method:"POST"|"PATCH"|"DELETE",body?:unknown){
    setBusy(true);setMessage("");
    try{
      const r=await fetch(path,{method,headers:{"Content-Type":"application/json"},...(body?{body:JSON.stringify(body)}:{})});
      const j=await r.json();
      if(!r.ok||!j.ok)throw new Error(j.error||"No se pudo completar la operación.");
      if(j.finance)setData(j.finance);else await refresh();
      setMessage("Cambios guardados en FLUX.");
      return true;
    }catch(e){setMessage(e instanceof Error?e.message:"Error al guardar.");return false;}
    finally{setBusy(false);}
  }
  function openNew(mode:Kind="expense"){
    setTab("transactions");setEditingTx(null);setTxMode(mode);setDraft({...blankDraft(data),type:mode==="transfer"?"expense":mode,category:categories.find(c=>c.type===(mode==="income"?"income":"expense"))?.name||"",fromAccountId:accounts.find(a=>a.is_active)?.id||"",toAccountId:accounts.find(a=>a.is_active&&a.id!==accounts.find(x=>x.is_active)?.id)?.id||""});setFormOpen(true);
  }
  function editTransaction(t:Tx){
    if(t.transfer_group){setMessage("Para proteger la integridad de las cuentas, las transferencias se editan como un par; elimina el traspaso no está permitido en esta versión.");return;}
    setEditingTx(t);setTxMode(t.type);setDraft({...blankDraft(data),type:t.type,category:t.category,description:t.description,amount:String(t.amount),date:String(t.transaction_date).slice(0,10),accountId:t.account_id||""});setFormOpen(true);setTab("transactions");
  }
  async function submitTransaction(e:FormEvent){
    e.preventDefault();
    const body=txMode==="transfer"?{action:"transfer.create",amount:draft.amount,date:draft.date,fromAccountId:draft.fromAccountId,toAccountId:draft.toAccountId}:{action:"transaction.create",type:txMode,category:draft.category,description:draft.description,amount:draft.amount,date:draft.date,accountId:draft.accountId||null};
    const ok=await mutate("/api/finance",editingTx?"PATCH":"POST",editingTx?{...body,entity:"transaction",id:editingTx.id}:body);
    if(ok){setFormOpen(false);setEditingTx(null);}
  }
  async function submitAccount(e:FormEvent){
    e.preventDefault();const ok=await mutate("/api/finance",accountEdit?"PATCH":"POST",accountEdit?{entity:"account",id:accountEdit.id,...accountEditDraft}:{action:"account.create",name:draft.name,accountType:draft.accountType,openingBalance:draft.openingBalance});
    if(ok){setFormOpen(false);setAccountEdit(null);setDraft(blankDraft(data));}
  }
  async function submitBudget(e:FormEvent){e.preventDefault();const ok=await mutate("/api/finance","POST",{action:"budget.create",...budgetDraft});if(ok)setBudgetDraft({name:"",category:"Vivienda",amountLimit:"",period:"monthly",startsOn:isoToday()});}
  async function submitGoal(e:FormEvent){e.preventDefault();const ok=await mutate("/api/finance","POST",{action:"goal.create",name:draft.name,targetAmount:draft.targetAmount,currentAmount:draft.currentAmount,targetDate:draft.targetDate||null});if(ok){setFormOpen(false);setDraft(blankDraft(data));}}
  async function submitRecurring(e:FormEvent){e.preventDefault();const ok=await mutate("/api/finance","POST",{action:"recurring.create",name:draft.name,type:draft.type,category:draft.category,description:draft.description,amount:draft.amount,frequency:draft.frequency,nextDate:draft.nextDate,accountId:draft.accountId||null});if(ok){setFormOpen(false);setDraft(blankDraft(data));}}
  async function submitCategory(e:FormEvent){e.preventDefault();const ok=await mutate("/api/finance","POST",{action:"category.create",...categoryDraft});if(ok)setCategoryDraft({name:"",type:"expense",color:"#FF6E75",icon:"circle"});}
  async function saveWidgets(next:Record<string,boolean>){await mutate("/api/finance","POST",{action:"preferences.update",preferences:{...preferences,widgets:next}});}
  function exportPDF(){
    if(!data)return;
    const doc=new jsPDF({unit:"mm",format:"a4"});
    const pageWidth=210;let y=18;
    doc.setFillColor(9,11,13);doc.rect(0,0,pageWidth,297,"F");
    doc.setTextColor(183,243,90);doc.setFont("helvetica","bold");doc.setFontSize(20);doc.text("FLUX",16,y);
    doc.setTextColor(225,230,234);doc.setFontSize(10);doc.text("REPORTE FINANCIERO PERSONAL",16,y+7);
    doc.setTextColor(137,147,155);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text("Generado "+new Date().toLocaleDateString("es-MX"),pageWidth-16,y,{align:"right"});
    y+=22;doc.setDrawColor(47,55,61);doc.line(16,y,pageWidth-16,y);y+=12;
    const box=(x:number,top:number,label:string,value:string,color:[number,number,number])=>{doc.setFillColor(18,22,25);doc.roundedRect(x,top,56,25,3,3,"F");doc.setTextColor(130,140,148);doc.setFontSize(7);doc.text(label.toUpperCase(),x+4,top+7);doc.setTextColor(...color);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text(value,x+4,top+16);doc.setFont("helvetica","normal");};
    box(16,y,"Saldo de cuentas",fmt(allBalance),[115,183,255]);box(77,y,"Ingresos del mes",fmt(thisMonthIncome),[183,243,90]);box(138,y,"Gastos del mes",fmt(thisMonthExpense),[255,110,117]);y+=35;
    doc.setTextColor(230,234,237);doc.setFont("helvetica","bold");doc.setFontSize(12);doc.text("Movimientos recientes",16,y);y+=7;
    const head=["Fecha","Tipo","Categoría / descripción","Cuenta","Importe"];
    const widths=[24,21,67,38,28];let x=16;
    doc.setFillColor(29,35,39);doc.rect(16,y-4,178,8,"F");doc.setFontSize(7);doc.setTextColor(201,210,216);
    head.forEach((h,i)=>{doc.text(h,x+2,y+1);x+=widths[i];});y+=9;
    const rows=displayTx.slice(0,22);
    for(const t of rows){
      if(y>267){doc.addPage();doc.setFillColor(9,11,13);doc.rect(0,0,pageWidth,297,"F");y=18;}
      x=16;doc.setFontSize(7);doc.setTextColor(176,184,190);
      const kind=t.transfer_group?"Traspaso":t.type==="income"?"Ingreso":"Gasto";
      const values=[dateFmt(t.transaction_date),kind,(t.category+" · "+(t.description||"")).slice(0,43),t.account_name||"Sin cuenta",fmt(Number(t.amount))];
      values.forEach((v,i)=>{const max=i===2?40:25;doc.text(doc.splitTextToSize(v,max)[0]||"",x+2,y);x+=widths[i];});
      if(t.type==="income"&&!t.transfer_group)doc.setTextColor(183,243,90);else if(t.type==="expense"&&!t.transfer_group)doc.setTextColor(255,110,117);else doc.setTextColor(115,183,255);
      doc.text(fmt(Number(t.amount)),188,y,{align:"right"});y+=7;
      doc.setDrawColor(39,45,49);doc.line(16,y-3,194,y-3);
    }
    y=Math.min(y+8,278);doc.setTextColor(139,148,155);doc.setFontSize(8);doc.text("Presupuestos activos: "+budgets.filter(b=>b.is_active).length+"   ·   Metas de ahorro: "+goals.filter(g=>g.status==="active").length+"   ·   Cuentas: "+accounts.filter(a=>a.is_active).length,16,y);
    doc.save("FLUX-reporte-"+isoToday()+".pdf");setMessage("Reporte PDF generado.");
  }
  const moneyDelta=(v:number)=>v>=0?"+":"−";

  return <div className="flux">
    <div className="fluxHero">
      <div><div className="fluxEyebrow"><span className="fluxLive"/> FLUX · FINANZAS PERSONALES</div><h1>Tu dinero,<br/><span>bajo control.</span></h1><p>El sistema completo de FLUX integrado a DEMian: registro manual, cálculos automáticos, cuentas, presupuestos, metas e informes.</p></div>
      <div className="fluxActions"><button className="fluxBtn ghost" onClick={()=>void refresh()} disabled={loading}>↻ Actualizar</button><button className="fluxBtn primary" onClick={()=>openNew("expense")}>＋ Movimiento</button></div>
    </div>
    <div className="fluxTabs">{tabs.map(t=><button key={t.id} onClick={()=>{setTab(t.id);setFormOpen(false);setMessage("");}} className={tab===t.id?"fluxTab active":"fluxTab"}><span>{t.glyph}</span>{t.label}</button>)}</div>
    {error&&<div className="fluxAlert error"><b>Conexión con FLUX pendiente</b><span>{error}</span><button onClick={()=>void refresh()}>Reintentar ↻</button></div>}
    {message&&<div className={message.includes("no ")||message.includes("No ")?"fluxAlert error":"fluxAlert"} role="status"><span>{message}</span><button onClick={()=>setMessage("")}>×</button></div>}
    {loading&&!data?<div className="fluxLoading"><div className="fluxSpinner"/><b>Conectando con FLUX</b><span>Consultando tus cuentas y movimientos.</span></div>:data&&<>
      {tab==="overview"&&<div className="fluxStack">
        <div className="fluxSectionHead"><div><h2>Vista financiera</h2><p>Resumen de {new Date().toLocaleDateString("es-MX",{month:"long",year:"numeric"})} basado en tus registros reales.</p></div><button className="fluxBtn ghost small" onClick={()=>setSettingsOpen(v=>!v)}>⚙ Personalizar panel</button></div>
        {settingsOpen&&<div className="fluxPanel widgetSettings"><div><b>Widgets visibles</b><p>Elige qué indicadores aparecen en tu panel.</p></div><div className="widgetToggles">{([{key:"balance",label:"Saldo total"},{key:"trends",label:"Tendencia mensual"},{key:"categories",label:"Distribución de gastos"},{key:"budgets",label:"Presupuestos"},{key:"goals",label:"Metas de ahorro"}] as const).map(w=><label key={w.key}><input type="checkbox" checked={prefsWidgets[w.key]!==false} onChange={e=>void saveWidgets({...prefsWidgets,[w.key]:e.target.checked})}/>{w.label}</label>)}</div></div>}
        <div className="fluxStats">
          {prefsWidgets.balance!==false&&<article className="fluxStat balanceStat"><div className="fluxStatTop"><span className="fluxStatIcon blue">◈</span><span>SALDO DISPONIBLE</span></div><strong>{fmt(allBalance)}</strong><p>Suma de las cuentas activas</p><small>Balance calculado desde saldo inicial y movimientos</small></article>}
          <article className="fluxStat"><div className="fluxStatTop"><span className="fluxStatIcon green">↗</span><span>INGRESOS DEL MES</span></div><strong className="fluxPositive">{fmt(thisMonthIncome)}</strong><p>{currentMonthTx.filter(monthIncome).length} movimientos de ingreso</p><small>Traspasos entre cuentas excluidos</small></article>
          <article className="fluxStat"><div className="fluxStatTop"><span className="fluxStatIcon red">↘</span><span>GASTOS DEL MES</span></div><strong className="fluxNegative">{fmt(thisMonthExpense)}</strong><p>{currentMonthTx.filter(monthExpense).length} movimientos de gasto</p><small>Traspasos entre cuentas excluidos</small></article>
          <article className="fluxStat"><div className="fluxStatTop"><span className="fluxStatIcon silver">≋</span><span>FLUJO NETO</span></div><strong className={currentNet>=0?"fluxPositive":"fluxNegative"}>{fmt(currentNet)}</strong><p>{currentNet>=0?"Vas en positivo este mes":"Tus gastos superan tus ingresos"}</p><small>Ingresos menos gastos del mes</small></article>
        </div>
        <div className="fluxTwoCol">
          {prefsWidgets.trends!==false&&<section className="fluxPanel"><div className="fluxPanelHead"><div><h3>Tu tendencia</h3><p>Flujo de los últimos 6 meses</p></div><span className="fluxBadge">6 MESES</span></div><div className="fluxTrend">{monthlySeries.map(s=>{const max=Math.max(1,...monthlySeries.flatMap(m=>[m.income,m.expense]));return <div className="fluxTrendCol" key={s.key}><div className="fluxBars"><div className="fluxBar income" title={"Ingresos "+fmt(s.income)} style={{height:Math.max(s.income?3:1,s.income/max*100)+"%"}}/><div className="fluxBar expense" title={"Gastos "+fmt(s.expense)} style={{height:Math.max(s.expense?3:1,s.expense/max*100)+"%"}}/></div><small>{s.label}</small></div>})}</div><div className="fluxLegend"><span><i className="fluxPositiveDot"/> Ingresos</span><span><i className="fluxNegativeDot"/> Gastos</span></div></section>}
          {prefsWidgets.categories!==false&&<section className="fluxPanel"><div className="fluxPanelHead"><div><h3>¿A dónde va tu dinero?</h3><p>Distribución de gastos de este mes</p></div><button className="fluxTextBtn" onClick={()=>setTab("reports")}>Ver informe ↗</button></div><div className="fluxPieWrap"><button aria-label="Ver distribución total" className="fluxPie" style={{background:pieCss}} onClick={()=>{setSelectedSlice("");setTab("reports");}}><span><b>{fmt(pieTotal)}</b><small>GASTOS DEL MES</small></span></button><div className="fluxPieLegend">{expenseByCategory.slice(0,5).map(c=><button key={c.name} onClick={()=>{setSelectedSlice(c.name);setCategoryFilter(c.name);setTab("transactions");}}><i style={{background:c.color}}/><span>{c.name}</span><b>{fmt(c.amount)}</b></button>)}{!expenseByCategory.length&&<div className="fluxEmptySmall">Registra un gasto para ver tu distribución.</div>}</div></div></section>}
        </div>
        <div className="fluxTwoCol">
          {prefsWidgets.budgets!==false&&<section className="fluxPanel"><div className="fluxPanelHead"><div><h3>Presupuestos</h3><p>Tu gasto contra tus límites</p></div><button className="fluxTextBtn" onClick={()=>setTab("budgets")}>Gestionar ↗</button></div>{budgetViews.slice(0,4).map(b=><div className="fluxBudgetMini" key={b.id}><div><b>{b.name}</b><span>{fmt(b.used)} de {fmt(Number(b.amount_limit))}</span></div><div className="fluxProgress"><i className={b.ratio>=100?"over":b.ratio>=80?"warn":""} style={{width:b.ratio+"%"}}/></div><small className={b.remaining<0?"fluxNegative":""}>{b.remaining<0?"Excedido por "+fmt(-b.remaining):"Restan "+fmt(b.remaining)} · {periodName(b.period)}</small></div>)}{!budgetViews.length&&<div className="fluxEmptySmall">Sin presupuestos activos. <button onClick={()=>setTab("budgets")}>Crear el primero ↗</button></div>}</section>}
          {prefsWidgets.goals!==false&&<section className="fluxPanel"><div className="fluxPanelHead"><div><h3>Metas de ahorro</h3><p>Avance hacia tus objetivos</p></div><button className="fluxTextBtn" onClick={()=>setTab("goals")}>Ver metas ↗</button></div>{goals.filter(g=>g.status==="active").slice(0,4).map(g=>{const p=Math.min(100,Number(g.current_amount)/Number(g.target_amount)*100);return <div className="fluxGoalMini" key={g.id}><div><b>{g.name}</b><strong>{Math.round(p)}%</strong></div><div className="fluxProgress goal"><i style={{width:p+"%"}}/></div><small>{fmt(g.current_amount)} de {fmt(g.target_amount)}{g.target_date?" · Meta "+dateFmt(g.target_date):""}</small></div>;})}{!goals.filter(g=>g.status==="active").length&&<div className="fluxEmptySmall">Define una meta y sigue su progreso. <button onClick={()=>setTab("goals")}>Crear meta ↗</button></div>}</section>}
        </div>
        <section className="fluxPanel"><div className="fluxPanelHead"><div><h3>Últimos movimientos</h3><p>Actividad reciente de tus registros</p></div><button className="fluxTextBtn" onClick={()=>setTab("transactions")}>Ver todos ↗</button></div><TransactionList rows={latest.slice(0,5)} onEdit={editTransaction} onDelete={async t=>{if(confirm("¿Eliminar este movimiento de FLUX?"))await mutate("/api/finance?entity=transaction&id="+encodeURIComponent(t.id),"DELETE");}}/></section>
        <div className="fluxQuickActions"><button onClick={()=>openNew("income")}><span className="quickIncome">↗</span><b>Registrar ingreso</b><small>Agregar dinero recibido</small></button><button onClick={()=>openNew("expense")}><span className="quickExpense">↘</span><b>Registrar gasto</b><small>Registrar una compra o pago</small></button><button onClick={()=>{setTab("accounts");setFormOpen(true);setDraft(blankDraft(data));}}><span className="quickAccount">▣</span><b>Nueva cuenta</b><small>Agregar efectivo o banco</small></button><button onClick={()=>{setTab("reports");exportPDF()}}><span className="quickPdf">▤</span><b>Reporte PDF</b><small>Exportar tus finanzas</small></button></div>
      </div>}
      {tab==="transactions"&&<div className="fluxStack">
        <div className="fluxSectionHead"><div><h2>Movimientos</h2><p>Historial completo con filtros y edición.</p></div><div className="fluxActions"><button className="fluxBtn ghost" onClick={()=>openNew("transfer")}>⇄ Transferir</button><button className="fluxBtn primary" onClick={()=>openNew("expense")}>＋ Añadir</button></div></div>
        <div className="fluxPanel"><div className="fluxFilters"><input aria-label="Buscar movimientos" placeholder="Buscar concepto, categoría o cuenta…" value={search} onChange={e=>setSearch(e.target.value)}/><select value={typeFilter} onChange={e=>setTypeFilter(e.target.value)}><option value="all">Todos los tipos</option><option value="income">Ingresos</option><option value="expense">Gastos</option><option value="transfer">Transferencias</option></select><select value={categoryFilter} onChange={e=>setCategoryFilter(e.target.value)}><option value="all">Todas las categorías</option>{categories.map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select></div><TransactionList rows={visibleTx} onEdit={editTransaction} onDelete={async t=>{if(confirm("¿Eliminar este movimiento de FLUX?"))await mutate("/api/finance?entity=transaction&id="+encodeURIComponent(t.id),"DELETE");}}/><div className="fluxListFooter">{visibleTx.length} movimientos visibles · Total histórico de ingresos/gastos: {fmt(allTransactionsAmount)}</div></div>
        {formOpen&&txForm()}
      </div>}
      {tab==="accounts"&&<div className="fluxStack"><div className="fluxSectionHead"><div><h2>Tus cuentas</h2><p>Saldo inicial y movimientos asociados determinan el saldo calculado.</p></div><button className="fluxBtn primary" onClick={()=>{setAccountEdit(null);setDraft(blankDraft(data));setFormOpen(v=>!v);}}>＋ Nueva cuenta</button></div><div className="fluxAccountGrid">{accounts.map(a=><article className="fluxAccountCard" key={a.id}><div className="fluxAccountTop"><span className="fluxStatIcon blue">{a.account_type==="cash"?"$":a.account_type==="bank"?"▣":a.account_type==="credit"?"▤":"◈"}</span><button className="fluxIconButton" aria-label="Editar cuenta" onClick={()=>{setAccountEdit(a);setAccountEditDraft({name:a.name,accountType:a.account_type,openingBalance:String(a.opening_balance),isActive:a.is_active});setFormOpen(true);}}>✎</button></div><span className="fluxMuted">{({cash:"EFECTIVO",bank:"CUENTA BANCARIA",credit:"CRÉDITO",other:"OTRA CUENTA"} as Record<string,string>)[a.account_type]||a.account_type.toUpperCase()}</span><h3>{a.name}</h3><strong>{fmt(a.balance)}</strong><small>Saldo actual calculado · Saldo inicial {fmt(a.opening_balance)}</small><span className={a.is_active?"fluxStatus active":"fluxStatus"}>{a.is_active?"Activa":"Inactiva"}</span></article>)}</div>{!accounts.length&&<Empty title="Todavía no hay cuentas" text="Crea una cuenta para organizar tus movimientos." action={()=>setFormOpen(true)}/>} {formOpen&&accountForm()}</div>}
      {tab==="budgets"&&<div className="fluxStack"><div className="fluxSectionHead"><div><h2>Presupuestos</h2><p>Define límites por categoría y detecta excesos antes de fin de periodo.</p></div></div><form className="fluxPanel fluxForm" onSubmit={submitBudget}><div className="fluxFormHeading"><b>Crear presupuesto</b><span>Control por semana, mes o año</span></div><div className="fluxFormGrid"><label>Nombre<input required maxLength={80} value={budgetDraft.name} onChange={e=>setBudgetDraft({...budgetDraft,name:e.target.value})} placeholder="Ej. Gastos del hogar"/></label><label>Categoría<select value={budgetDraft.category} onChange={e=>setBudgetDraft({...budgetDraft,category:e.target.value})}>{categories.filter(c=>c.type==="expense").map(c=><option key={c.id}>{c.name}</option>)}</select></label><label>Límite en MXN<input required min="0.01" step="0.01" type="number" value={budgetDraft.amountLimit} onChange={e=>setBudgetDraft({...budgetDraft,amountLimit:e.target.value})} placeholder="5000"/></label><label>Periodo<select value={budgetDraft.period} onChange={e=>setBudgetDraft({...budgetDraft,period:e.target.value})}><option value="weekly">Semanal</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></label><label>Inicia el<input type="date" required value={budgetDraft.startsOn} onChange={e=>setBudgetDraft({...budgetDraft,startsOn:e.target.value})}/></label></div><div className="fluxFormActions"><button className="fluxBtn primary" disabled={busy}>Guardar presupuesto</button></div></form><div className="fluxBudgetGrid">{budgetViews.map(b=><article className="fluxPanel fluxBudgetCard" key={b.id}><div className="fluxPanelHead"><div><span className="fluxMuted">{periodName(b.period).toUpperCase()}</span><h3>{b.name}</h3><p>{b.category}</p></div><button className="fluxIconButton" aria-label="Desactivar presupuesto" onClick={()=>void mutate("/api/finance","PATCH",{entity:"budget",id:b.id,isActive:false})}>×</button></div><div className="fluxBudgetNumbers"><strong>{fmt(b.used)}</strong><span>de {fmt(b.amount_limit)}</span></div><div className="fluxProgress"><i className={b.ratio>=100?"over":b.ratio>=80?"warn":""} style={{width:b.ratio+"%"}}/></div><div className="fluxBudgetFoot"><b>{Math.round(b.ratio)}% utilizado</b><span className={b.remaining<0?"fluxNegative":""}>{b.remaining<0?"Excedido "+fmt(-b.remaining):"Restan "+fmt(b.remaining)}</span></div><small>Periodo actual desde {dateFmt(b.starts_on)}</small></article>)}</div>{!budgets.filter(b=>b.is_active).length&&<Empty title="Sin presupuestos activos" text="Define cuánto quieres gastar por categoría."/>}</div>}
      {tab==="goals"&&<div className="fluxStack"><div className="fluxSectionHead"><div><h2>Metas de ahorro</h2><p>Objetivos medibles para crear un fondo, comprar algo o pagar una deuda.</p></div><button className="fluxBtn primary" onClick={()=>{setDraft(blankDraft(data));setFormOpen(v=>!v);}}>＋ Nueva meta</button></div>{formOpen&&goalForm()}<div className="fluxGoalGrid">{goals.map(g=>{const p=Math.min(100,Number(g.current_amount)/Number(g.target_amount)*100);return <article className="fluxPanel fluxGoalCard" key={g.id}><div className="fluxGoalOrbit">◎</div><span className={"fluxStatus "+(g.status==="active"?"active":g.status==="completed"?"completed":"")}>{g.status==="active"?"En progreso":g.status==="completed"?"Completada":"En pausa"}</span><h3>{g.name}</h3><strong>{fmt(g.current_amount)}</strong><small>de {fmt(g.target_amount)}</small><div className="fluxProgress goal"><i style={{width:p+"%"}}/></div><div className="fluxGoalFoot"><b>{Math.round(p)}% completado</b><span>Faltan {fmt(Math.max(0,g.target_amount-g.current_amount))}</span></div>{g.target_date&&<p className="fluxSubtle">Fecha objetivo: {dateFmt(g.target_date)}</p>}{g.status!=="completed"&&<div className="fluxGoalContribute"><input type="number" min="0.01" step="0.01" placeholder="Abono MXN" value={goalAdds[g.id]||""} onChange={e=>setGoalAdds({...goalAdds,[g.id]:e.target.value})}/><button className="fluxBtn primary small" disabled={busy||!goalAdds[g.id]} onClick={async()=>{const ok=await mutate("/api/finance","PATCH",{entity:"goal",id:g.id,addAmount:goalAdds[g.id]});if(ok)setGoalAdds({...goalAdds,[g.id]:""});}}>Abonar</button><button className="fluxIconButton" title="Pausar meta" onClick={()=>void mutate("/api/finance","PATCH",{entity:"goal",id:g.id,addAmount:0,status:g.status==="paused"?"active":"paused"})}>{g.status==="paused"?"▶":"Ⅱ"}</button></div>}</article>;})}</div>{!goals.length&&!formOpen&&<Empty title="Crea tu primera meta" text="Ponle nombre, monto objetivo y fecha para medir tu avance." action={()=>setFormOpen(true)}/>}</div>}
      {tab==="recurring"&&<div className="fluxStack"><div className="fluxSectionHead"><div><h2>Movimientos recurrentes</h2><p>Servicios, rentas, suscripciones o ingresos fijos con próxima fecha registrada.</p></div><button className="fluxBtn primary" onClick={()=>{setDraft(blankDraft(data));setFormOpen(v=>!v);}}>＋ Añadir recurrente</button></div>{formOpen&&recurringForm()}<div className="fluxPanel"><div className="fluxPanelHead"><div><h3>Calendario de recurrencias</h3><p>La app no ejecuta pagos por sí sola: confirma manualmente para registrar cada ocurrencia.</p></div><span className="fluxBadge">{dueRecurring.length} POR REGISTRAR</span></div><div className="fluxRecurringList">{recurring.map(r=><div className="fluxRecurringRow" key={r.id}><span className={"fluxRecurringIcon "+r.type}>{r.type==="income"?"↗":"↘"}</span><div className="fluxRecurringMain"><b>{r.name}</b><small>{r.category} · {({weekly:"Cada semana",biweekly:"Cada 2 semanas",monthly:"Cada mes",yearly:"Cada año"} as Record<string,string>)[r.frequency]}</small><small>Próxima fecha: {dateFmt(r.next_date)}{r.description?" · "+r.description:""}</small></div><strong className={r.type==="income"?"fluxPositive":"fluxNegative"}>{r.type==="income"?"+":"−"}{fmt(r.amount)}</strong><div className="fluxRecurringActions">{r.is_active&&r.next_date<=isoToday()&&<button className="fluxBtn primary small" disabled={busy} onClick={()=>void mutate("/api/finance","POST",{action:"recurring.post",id:r.id})}>Registrar</button>}<button className="fluxIconButton" title={r.is_active?"Pausar":"Reactivar"} onClick={()=>void mutate("/api/finance","PATCH",{entity:"recurring",id:r.id,isActive:!r.is_active})}>{r.is_active?"Ⅱ":"▶"}</button><button className="fluxIconButton danger" title="Eliminar recurrente" onClick={()=>{if(confirm("¿Eliminar esta regla recurrente?"))void mutate("/api/finance?entity=recurring&id="+encodeURIComponent(r.id),"DELETE");}}>×</button></div></div>)}</div>{!recurring.length&&<Empty title="Sin recurrencias" text="Añade pagos o ingresos recurrentes para que FLUX te los recuerde y permita registrarlos."/>}</div></div>}
      {tab==="reports"&&<div className="fluxStack"><div className="fluxSectionHead"><div><h2>Informes financieros</h2><p>Distribución de gastos, tendencias e historial para analizar o guardar en PDF.</p></div><button className="fluxBtn primary" onClick={exportPDF}>↓ Exportar PDF</button></div><div className="fluxPanel"><div className="fluxPanelHead"><div><h3>Reporte por mes</h3><p>Elige cualquier mes de tu historial.</p></div><input type="month" value={periodFilter} onChange={e=>setPeriodFilter(e.target.value)}/></div>{(()=>{const period=transactions.filter(t=>String(t.transaction_date).slice(0,7)===periodFilter),inc=period.filter(monthIncome).reduce((s,t)=>s+Number(t.amount),0),exp=period.filter(monthExpense).reduce((s,t)=>s+Number(t.amount),0);return <div className="fluxReportStats"><div><span>Ingresos</span><b className="fluxPositive">{fmt(inc)}</b></div><div><span>Gastos</span><b className="fluxNegative">{fmt(exp)}</b></div><div><span>Flujo neto</span><b className={inc-exp>=0?"fluxPositive":"fluxNegative"}>{fmt(inc-exp)}</b></div><div><span>Movimientos</span><b>{period.filter(t=>!t.transfer_group).length}</b></div></div>;})()}</div><div className="fluxTwoCol"><section className="fluxPanel"><div className="fluxPanelHead"><div><h3>Distribución interactiva</h3><p>Selecciona una categoría para filtrar movimientos.</p></div></div><div className="fluxPieWrap large"><div className="fluxPie" style={{background:periodFilter===currentMonth?pieCss:pieFor(periodFilter)}}><span><b>{fmt(transactions.filter(t=>String(t.transaction_date).slice(0,7)===periodFilter&&monthExpense(t)).reduce((s,t)=>s+Number(t.amount),0))}</b><small>GASTOS DEL MES</small></span></div><div className="fluxPieLegend">{pieByPeriod(periodFilter).map(c=><button key={c.name} className={selectedSlice===c.name?"selected":""} onClick={()=>{setSelectedSlice(selectedSlice===c.name?"":c.name);setCategoryFilter(selectedSlice===c.name?"all":c.name);setTab("transactions");}}><i style={{background:c.color}}/><span>{c.name}</span><b>{fmt(c.amount)}</b></button>)}{!pieByPeriod(periodFilter).length&&<div className="fluxEmptySmall">Sin gastos registrados en este periodo.</div>}</div></div></section><section className="fluxPanel"><div className="fluxPanelHead"><div><h3>Comparativo semestral</h3><p>Ingresos frente a gastos.</p></div></div><div className="fluxReportChart">{monthlySeries.map(s=>{const max=Math.max(1,...monthlySeries.flatMap(m=>[m.income,m.expense]));return <div key={s.key} className="fluxReportMonth"><div className="fluxReportBarPair"><div className="fluxReportBar income" style={{height:Math.max(s.income?3:1,s.income/max*100)+"%"}} title={fmt(s.income)}/><div className="fluxReportBar expense" style={{height:Math.max(s.expense?3:1,s.expense/max*100)+"%"}} title={fmt(s.expense)}/></div><small>{s.label}</small></div>})}</div><div className="fluxLegend"><span><i className="fluxPositiveDot"/> Ingresos</span><span><i className="fluxNegativeDot"/> Gastos</span></div></section></div><section className="fluxPanel"><div className="fluxPanelHead"><div><h3>Desglose del periodo</h3><p>{periodFilter}</p></div></div><TransactionList rows={groupTransfers(transactions.filter(t=>String(t.transaction_date).slice(0,7)===periodFilter))} onEdit={editTransaction} onDelete={async t=>{if(confirm("¿Eliminar este movimiento?"))await mutate("/api/finance?entity=transaction&id="+encodeURIComponent(t.id),"DELETE");}}/></section></div>}
      {tab==="categories"&&<div className="fluxStack"><div className="fluxSectionHead"><div><h2>Categorías</h2><p>Personaliza cómo clasificas ingresos y gastos.</p></div></div><form className="fluxPanel fluxForm" onSubmit={submitCategory}><div className="fluxFormHeading"><b>Añadir categoría</b><span>Úsala en movimientos y recurrentes.</span></div><div className="fluxFormGrid"><label>Nombre<input required maxLength={80} value={categoryDraft.name} onChange={e=>setCategoryDraft({...categoryDraft,name:e.target.value})} placeholder="Ej. Mascotas"/></label><label>Tipo<select value={categoryDraft.type} onChange={e=>setCategoryDraft({...categoryDraft,type:e.target.value,color:e.target.value==="income"?"#B7F35A":"#FF6E75"})}><option value="income">Ingreso</option><option value="expense">Gasto</option></select></label><label>Color<input type="color" value={categoryDraft.color} onChange={e=>setCategoryDraft({...categoryDraft,color:e.target.value})}/></label></div><div className="fluxFormActions"><button className="fluxBtn primary" disabled={busy}>Guardar categoría</button></div></form><div className="fluxCategoryGrid">{(["income","expense"] as const).map(type=><section className="fluxPanel" key={type}><div className="fluxPanelHead"><div><h3>{type==="income"?"Categorías de ingreso":"Categorías de gasto"}</h3><p>{categories.filter(c=>c.type===type).length} categorías</p></div></div>{categories.filter(c=>c.type===type).map(c=><div className="fluxCategoryRow" key={c.id}><i style={{background:c.color}}/><b>{c.name}</b>{c.is_default&&<span className="fluxBadge">BASE</span>} {!c.is_default&&<button className="fluxIconButton danger" title="Eliminar categoría" onClick={()=>{if(confirm("¿Eliminar esta categoría?"))void mutate("/api/finance?entity=category&id="+encodeURIComponent(c.id),"DELETE");}}>×</button>}</div>)}</section>)}</div></div>}
    </>}
  </div>;

  function txForm(){return <div className="fluxModalBackdrop" onClick={()=>setFormOpen(false)}><form className="fluxModal" onSubmit={submitTransaction} onClick={e=>e.stopPropagation()}><div className="fluxModalHead"><div><h3>{editingTx?"Editar movimiento":txMode==="transfer"?"Transferir entre cuentas":txMode==="income"?"Registrar ingreso":"Registrar gasto"}</h3><p>Se guarda directamente en la base de datos de FLUX.</p></div><button type="button" className="fluxIconButton" onClick={()=>setFormOpen(false)}>×</button></div>{!editingTx&&<div className="fluxKindSwitch"><button type="button" onClick={()=>{setTxMode("income");setDraft({...draft,type:"income",category:categories.find(c=>c.type==="income")?.name||""});}} className={txMode==="income"?"income selected":"income"}>↗ Ingreso</button><button type="button" onClick={()=>{setTxMode("expense");setDraft({...draft,type:"expense",category:categories.find(c=>c.type==="expense")?.name||""});}} className={txMode==="expense"?"expense selected":"expense"}>↘ Gasto</button><button type="button" onClick={()=>setTxMode("transfer")} className={txMode==="transfer"?"transfer selected":"transfer"}>⇄ Traspaso</button></div>}<label>Concepto<input required maxLength={500} value={draft.description} onChange={e=>setDraft({...draft,description:e.target.value})} placeholder={txMode==="income"?"Ej. Pago de sueldo":txMode==="transfer"?"Ej. Pasar dinero al banco":"Ej. Despensa semanal"}/></label><div className="fluxFormGrid two"><label>Importe (MXN)<input required type="number" min=".01" step=".01" value={draft.amount} onChange={e=>setDraft({...draft,amount:e.target.value})} placeholder="0.00"/></label><label>Fecha<input required type="date" value={draft.date} onChange={e=>setDraft({...draft,date:e.target.value})}/></label></div>{txMode==="transfer"?<div className="fluxFormGrid two"><label>Desde<select required value={draft.fromAccountId} onChange={e=>setDraft({...draft,fromAccountId:e.target.value})}>{accounts.filter(a=>a.is_active).map(a=><option key={a.id} value={a.id}>{a.name} · {fmt(a.balance)}</option>)}</select></label><label>Hacia<select required value={draft.toAccountId} onChange={e=>setDraft({...draft,toAccountId:e.target.value})}><option value="">Selecciona destino</option>{accounts.filter(a=>a.is_active&&a.id!==draft.fromAccountId).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label></div>:<div className="fluxFormGrid two"><label>Categoría<select required value={draft.category} onChange={e=>setDraft({...draft,category:e.target.value})}>{categories.filter(c=>c.type===txMode).map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select></label><label>Cuenta<select value={draft.accountId} onChange={e=>setDraft({...draft,accountId:e.target.value})}><option value="">Sin asignar</option>{accounts.filter(a=>a.is_active).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label></div>}<div className="fluxModalActions"><button type="button" className="fluxBtn ghost" onClick={()=>setFormOpen(false)}>Cancelar</button><button className="fluxBtn primary" disabled={busy}>{busy?"Guardando…":editingTx?"Guardar cambios":"Guardar movimiento"}</button></div></form></div>;}
  function accountForm(){return <div className="fluxModalBackdrop" onClick={()=>{setFormOpen(false);setAccountEdit(null);}}><form className="fluxModal" onSubmit={submitAccount} onClick={e=>e.stopPropagation()}><div className="fluxModalHead"><div><h3>{accountEdit?"Editar cuenta":"Nueva cuenta"}</h3><p>El saldo actual se recalcula con todos sus movimientos.</p></div><button type="button" className="fluxIconButton" onClick={()=>{setFormOpen(false);setAccountEdit(null);}}>×</button></div><label>Nombre<input required maxLength={80} value={accountEdit?accountEditDraft.name:draft.name} onChange={e=>accountEdit?setAccountEditDraft({...accountEditDraft,name:e.target.value}):setDraft({...draft,name:e.target.value})} placeholder="Ej. Cuenta de nómina"/></label><div className="fluxFormGrid two"><label>Tipo<select value={accountEdit?accountEditDraft.accountType:draft.accountType} onChange={e=>accountEdit?setAccountEditDraft({...accountEditDraft,accountType:e.target.value}):setDraft({...draft,accountType:e.target.value})}><option value="cash">Efectivo</option><option value="bank">Banco</option><option value="credit">Crédito</option><option value="other">Otro</option></select></label><label>Saldo inicial<input required type="number" step=".01" value={accountEdit?accountEditDraft.openingBalance:draft.openingBalance} onChange={e=>accountEdit?setAccountEditDraft({...accountEditDraft,openingBalance:e.target.value}):setDraft({...draft,openingBalance:e.target.value})}/></label></div>{accountEdit&&<label className="fluxCheck"><input type="checkbox" checked={accountEditDraft.isActive} onChange={e=>setAccountEditDraft({...accountEditDraft,isActive:e.target.checked})}/> Cuenta activa</label>}<div className="fluxModalActions"><button type="button" className="fluxBtn ghost" onClick={()=>{setFormOpen(false);setAccountEdit(null);}}>Cancelar</button><button className="fluxBtn primary" disabled={busy}>{busy?"Guardando…":accountEdit?"Actualizar cuenta":"Crear cuenta"}</button></div></form></div>;}
  function goalForm(){return <div className="fluxModalBackdrop" onClick={()=>setFormOpen(false)}><form className="fluxModal" onSubmit={submitGoal} onClick={e=>e.stopPropagation()}><div className="fluxModalHead"><div><h3>Nueva meta de ahorro</h3><p>Define cuánto quieres ahorrar y para cuándo.</p></div><button type="button" className="fluxIconButton" onClick={()=>setFormOpen(false)}>×</button></div><label>Nombre de la meta<input required maxLength={100} value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="Ej. Fondo de emergencia"/></label><div className="fluxFormGrid two"><label>Monto objetivo<input required type="number" min=".01" step=".01" value={draft.targetAmount} onChange={e=>setDraft({...draft,targetAmount:e.target.value})} placeholder="30000"/></label><label>Ahorro actual<input type="number" min="0" step=".01" value={draft.currentAmount} onChange={e=>setDraft({...draft,currentAmount:e.target.value})}/></label></div><label>Fecha objetivo (opcional)<input type="date" value={draft.targetDate} onChange={e=>setDraft({...draft,targetDate:e.target.value})}/></label><div className="fluxModalActions"><button type="button" className="fluxBtn ghost" onClick={()=>setFormOpen(false)}>Cancelar</button><button className="fluxBtn primary" disabled={busy}>Crear meta</button></div></form></div>;}
  function recurringForm(){return <div className="fluxModalBackdrop" onClick={()=>setFormOpen(false)}><form className="fluxModal" onSubmit={submitRecurring} onClick={e=>e.stopPropagation()}><div className="fluxModalHead"><div><h3>Nueva recurrencia</h3><p>FLUX la recordará y te pedirá confirmar el registro cuando toque.</p></div><button type="button" className="fluxIconButton" onClick={()=>setFormOpen(false)}>×</button></div><label>Concepto<input required value={draft.name} maxLength={100} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="Ej. Internet, renta, nómina"/></label><div className="fluxFormGrid two"><label>Tipo<select value={draft.type} onChange={e=>setDraft({...draft,type:e.target.value,category:categories.find(c=>c.type===e.target.value)?.name||"",color:e.target.value==="income"?"#B7F35A":"#FF6E75"})}><option value="expense">Gasto</option><option value="income">Ingreso</option></select></label><label>Importe<input required type="number" min=".01" step=".01" value={draft.amount} onChange={e=>setDraft({...draft,amount:e.target.value})}/></label><label>Categoría<select required value={draft.category} onChange={e=>setDraft({...draft,category:e.target.value})}>{categories.filter(c=>c.type===draft.type).map(c=><option key={c.id}>{c.name}</option>)}</select></label><label>Frecuencia<select value={draft.frequency} onChange={e=>setDraft({...draft,frequency:e.target.value})}><option value="weekly">Semanal</option><option value="biweekly">Cada dos semanas</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></label><label>Próxima fecha<input type="date" required value={draft.nextDate} onChange={e=>setDraft({...draft,nextDate:e.target.value})}/></label><label>Cuenta<select value={draft.accountId} onChange={e=>setDraft({...draft,accountId:e.target.value})}><option value="">Sin asignar</option>{accounts.filter(a=>a.is_active).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label></div><label>Detalles<input value={draft.description} maxLength={500} onChange={e=>setDraft({...draft,description:e.target.value})} placeholder="Notas adicionales"/></label><div className="fluxModalActions"><button type="button" className="fluxBtn ghost" onClick={()=>setFormOpen(false)}>Cancelar</button><button className="fluxBtn primary" disabled={busy}>Guardar recurrencia</button></div></form></div>;}
  function pieByPeriod(period:string){const m=new Map<string,number>();for(const t of transactions.filter(t=>String(t.transaction_date).slice(0,7)===period&&monthExpense(t)))m.set(t.category,(m.get(t.category)||0)+Number(t.amount));return [...m.entries()].map(([name,amount],i)=>({name,amount,color:categories.find(c=>c.type==="expense"&&c.name===name)?.color||CAT_COLORS[i%CAT_COLORS.length]})).sort((a,b)=>b.amount-a.amount);}
  function pieFor(period:string){const slices=pieByPeriod(period);const total=slices.reduce((s,c)=>s+c.amount,0);if(!total)return "conic-gradient(#252b30 0deg 360deg)";let off=0;return "conic-gradient("+slices.map(c=>{const end=off+c.amount/total*360;const str=`${c.color} ${off}deg ${end}deg`;off=end;return str;}).join(",")+")";}
}
function TransactionList({rows,onEdit,onDelete}:{rows:Tx[];onEdit:(t:Tx)=>void;onDelete:(t:Tx)=>void}){
 if(!rows.length)return <div className="fluxEmpty"><span>↗</span><b>No hay movimientos para mostrar</b><p>Los registros aparecerán cuando captures ingresos o gastos.</p></div>;
 return <div className="fluxTransactionList">{rows.map(t=><div className="fluxTransactionRow" key={t.id}><span className={"fluxTxIcon "+(t.transfer_group?"transfer":t.type)}>{t.transfer_group?"⇄":t.type==="income"?"↗":"↘"}</span><div className="fluxTxMain"><b>{t.transfer_group?(t.account_name||"Cuenta")+" → "+(t.transfer_to_account_name||"Cuenta"):(t.description||t.category)}</b><small>{t.transfer_group?"Traspaso entre cuentas":t.category+" · "+(t.account_name||"Sin cuenta")} · {dateFmt(t.transaction_date)}</small></div><strong className={t.transfer_group?"fluxBlue":t.type==="income"?"fluxPositive":"fluxNegative"}>{t.transfer_group?"⇄":t.type==="income"?"+":"−"}{fmt(Number(t.amount))}</strong><button className="fluxIconButton" aria-label="Editar movimiento" onClick={()=>onEdit(t)} disabled={!!t.transfer_group}>✎</button><button className="fluxIconButton danger" aria-label="Eliminar movimiento" onClick={()=>onDelete(t)} disabled={!!t.transfer_group}>×</button></div>)}</div>;
}
function Empty({title,text,action}:{title:string;text:string;action?:()=>void}){
 return <div className="fluxEmpty"><span>✧</span><b>{title}</b><p>{text}</p>{action&&<button className="fluxBtn primary" onClick={action}>＋ Crear nuevo</button>}</div>;
}
